public class MemoryDemo {
    record Person(String name) {}                 // objects of this type live on the heap

    static String greet(Person who) {             // new stack frame holding the reference `who`
        String msg = "Hi " + who.name();          // msg -> new String object on the heap
        return msg;                               // frame is popped; the String survives via the caller
    }

    public static void main(String[] args) {
        int count = 1;                            // primitive: stored directly in main's frame
        Person p = new Person("Rahim");           // p (stack) -> Person object (heap)
        String s = greet(p);                      // s -> "Hi Rahim" (heap)
        p = null;                                 // the Person object is now unreachable
        System.gc();                              // only a HINT; the JVM decides when to collect
        System.out.println(s + " x" + count);     // Hi Rahim x1
    }
}

public class StringDemo {
    public static void main(String[] args) {
        String a = "java";                    // literal -> String pool
        String b = "java";                    // same literal -> SAME pooled object
        String c = new String("java");        // forces a new object on the heap
        System.out.println(a == b);           // true  (same reference)
        System.out.println(a == c);           // false (different objects)
        System.out.println(a.equals(c));      // true  (same characters)
        System.out.println(a == c.intern());  // true  (intern() returns the pooled copy)

        String d = a.concat(" 21");           // every "modifying" method returns a NEW String
        System.out.println(a + " | " + d);    // java | java 21   (a never changed)

        StringBuilder sb = new StringBuilder(4);
        sb.append("Hi").append(", ");         // fills the 4-char buffer in place
        System.out.println(sb.capacity());    // 4
        sb.append("Java");                    // needs 8 chars -> new buffer of 4 * 2 + 2 = 10
        System.out.println(sb.capacity());    // 10
        System.out.println(sb.reverse());     // avaJ ,iH   (same object, mutated)

        StringBuilder csv = new StringBuilder();
        for (int i = 1; i <= 5; i++) csv.append(i).append(i < 5 ? "," : "");
        System.out.println(csv);              // 1,2,3,4,5   O(n) total, no temp Strings
    }
}

import java.util.*;

public class EqualsHashCodeDemo {
    // BROKEN: equals() overridden, hashCode() inherited from Object (identity-based)
    static class BadEmployee {
        final String email;
        BadEmployee(String email) { this.email = email; }
        @Override public boolean equals(Object o) {
            return o instanceof BadEmployee other && email.equals(other.email);
        }
    }

    // CORRECT: both methods use the same field(s)
    static final class Employee {
        private final String email;
        private final String name;               // not part of identity
        Employee(String email, String name) { this.email = email; this.name = name; }

        @Override public boolean equals(Object o) {
            if (this == o) return true;                       // reflexive + fast path
            if (!(o instanceof Employee other)) return false; // also handles null
            return email.equals(other.email);
        }
        @Override public int hashCode() { return Objects.hash(email); }
    }

    record EmployeeRecord(String email) {}       // Java 16+: equals/hashCode/toString generated

    public static void main(String[] args) {
        Set<BadEmployee> bad = new HashSet<>();
        bad.add(new BadEmployee("rahim@bank.com"));
        System.out.println(bad.contains(new BadEmployee("rahim@bank.com")));   // false

        Set<Employee> good = new HashSet<>();
        good.add(new Employee("rahim@bank.com", "Rahim"));
        System.out.println(good.contains(new Employee("rahim@bank.com", "R. Uddin"))); // true
        good.add(new Employee("rahim@bank.com", "Rahim Uddin"));               // duplicate -> ignored
        System.out.println(good.size());                                       // 1

        System.out.println(new EmployeeRecord("a@b.com").equals(new EmployeeRecord("a@b.com"))); // true
    }
}

import java.util.*;

public class HashMapInternals {
    // Step 1 inside HashMap.hash(): mix the high 16 bits into the low 16 bits
    static int spread(Object key) {
        int h;
        return (key == null) ? 0 : (h = key.hashCode()) ^ (h >>> 16);
    }

    // Step 2: capacity is always a power of two, so (n - 1) & hash == hash % n (but faster)
    static int bucketIndex(Object key, int capacity) {
        return (capacity - 1) & spread(key);
    }

    public static void main(String[] args) {
        for (String city : List.of("Dhaka", "Rajshahi", "Khulna", "Noakhali")) {
            System.out.printf("%-8s hashCode=%11d  index(cap 4)=%d  index(cap 8)=%d%n",
                    city, city.hashCode(), bucketIndex(city, 4), bucketIndex(city, 8));
        }
        // Dhaka    hashCode=   65994323  index(cap 4)=1  index(cap 8)=5
        // Rajshahi hashCode=  214160274  index(cap 4)=1  index(cap 8)=1
        // Khulna   hashCode=-2048141945  index(cap 4)=0  index(cap 8)=4
        // Noakhali hashCode= 1107952769  index(cap 4)=3  index(cap 8)=3

        Map<String, Integer> branches = new HashMap<>(4);   // capacity 4, threshold 4 * 0.75 = 3
        branches.put("Dhaka", 120);
        branches.put("Rajshahi", 35);   // same bucket as Dhaka -> chained
        branches.put("Khulna", 40);
        branches.put("Noakhali", 18);   // size 4 > threshold 3 -> resize to 8 buckets
        branches.put("Dhaka", 125);     // same key -> value replaced, size stays 4
        System.out.println(branches.get("Rajshahi") + " " + branches.size());  // 35 4
    }
}

import java.util.*;

public class ListsDemo {
    public static void main(String[] args) {
        List<String> array = new ArrayList<>(4);      // backed by an Object[4]
        List<String> linked = new LinkedList<>();     // doubly linked nodes
        for (String s : List.of("A", "B", "C", "D", "E")) {
            array.add(s);                             // "E" triggers a grow: 4 -> 4 + 4/2 = 6
            linked.add(s);                            // always O(1): link a new last node
        }
        System.out.println(array.get(3));             // D   O(1): elementData[3]
        System.out.println(linked.get(3));            // D   O(n): walks node by node

        array.add(1, "X");                            // shifts B..E one slot right: O(n)
        linked.add(1, "X");                           // walk to index 1 (O(n)), relink (O(1))
        System.out.println(array.equals(linked));     // true  [A, X, B, C, D, E]

        ListIterator<String> it = linked.listIterator();
        while (it.hasNext()) {
            if (it.next().equals("C")) it.add("Y");   // O(1) insert at the cursor
        }
        System.out.println(linked);                   // [A, X, B, C, Y, D, E]

        Deque<String> queue = new ArrayDeque<>();     // better than LinkedList for queue/stack
        queue.offer("job1");
        queue.offer("job2");
        System.out.println(queue.poll());             // job1
    }
}

import java.io.*;
import java.nio.file.*;

public class ExceptionsDemo {
    // Business rule violation -> custom UNCHECKED exception
    static class InsufficientFundsException extends RuntimeException {
        InsufficientFundsException(String message) { super(message); }
    }

    // CHECKED: callers must catch IOException or declare it with `throws`
    static String readFirstLine(Path path) throws IOException {
        try (BufferedReader in = Files.newBufferedReader(path)) {   // closed automatically
            return in.readLine();
        }
    }

    static void withdraw(long balance, long amount) {
        if (amount <= 0) throw new IllegalArgumentException("amount must be positive");
        if (amount > balance) throw new InsufficientFundsException(balance + " < " + amount);
    }

    static void transfer(long balance, long amount) {
        System.out.println("transfer started");
        try {
            withdraw(balance, amount);
            System.out.println("never printed when withdraw throws");
        } finally {
            System.out.println("transfer cleanup (finally)");     // runs on success AND failure
        }
    }

    public static void main(String[] args) {
        try {
            readFirstLine(Path.of("missing.properties"));
        } catch (NoSuchFileException e) {                    // most specific catch first
            System.out.println("config missing: " + e.getMessage());
        } catch (IOException e) {
            throw new UncheckedIOException("cannot read config", e);  // wrap, keep the cause
        }

        try {
            transfer(500, 800);
        } catch (InsufficientFundsException | IllegalArgumentException e) {  // multi-catch
            System.out.println("rejected: " + e.getMessage());
        }
    }
}

