import java.util.*;

public class CollectionsDemo {
    public static void main(String[] args) {
        List<String> names = List.of("Rina", "Arif", "Mitu", "Arif");   // immutable (Java 9)

        System.out.println(new ArrayList<>(names));     // [Rina, Arif, Mitu, Arif] order + duplicates
        System.out.println(new LinkedHashSet<>(names)); // [Rina, Arif, Mitu]       insertion order, unique
        System.out.println(new TreeSet<>(names));       // [Arif, Mitu, Rina]       sorted, unique
        Set<String> hashed = new HashSet<>(names);      // unique, order depends on hash codes
        System.out.println(hashed.size());              // 3

        Map<String, Integer> scores = new TreeMap<>(Map.of("Rina", 90, "Arif", 75));
        System.out.println(scores);                     // {Arif=75, Rina=90}  sorted by key

        Deque<Integer> stack = new ArrayDeque<>();      // use instead of legacy Stack
        stack.push(1);
        stack.push(2);
        System.out.println(stack.pop());                // 2

        Queue<Integer> pq = new PriorityQueue<>(List.of(5, 1, 3));
        System.out.println(pq.poll());                  // 1   (min-heap)

        SequencedCollection<String> seq = new LinkedHashSet<>(names);   // Java 21
        System.out.println(seq.reversed());             // [Mitu, Arif, Rina]

        try {
            names.add("Zara");
        } catch (UnsupportedOperationException e) {
            System.out.println("List.of(...) is unmodifiable");
        }
    }
}

import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

public class ConcurrencyDemo {
    static int unsafeCount = 0;                         // shared and unprotected
    static int syncCount = 0;
    static final Object lock = new Object();
    static final AtomicInteger atomicCount = new AtomicInteger();
    static volatile boolean running = true;             // volatile: writes are visible to all threads

    public static void main(String[] args) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(4);   // 4 reusable worker threads
        List<Callable<Void>> tasks = new ArrayList<>();
        for (int t = 0; t < 4; t++) {
            tasks.add(() -> {
                for (int i = 0; i < 100_000; i++) {
                    unsafeCount++;                       // read-modify-write: NOT atomic
                    synchronized (lock) { syncCount++; } // one thread at a time
                    atomicCount.incrementAndGet();       // lock-free compare-and-set
                }
                return null;
            });
        }
        pool.invokeAll(tasks);                           // blocks until all tasks finish
        pool.shutdown();                                 // no new tasks; threads exit when idle
        System.out.println("unsafe = " + unsafeCount);   // usually < 400000 (lost updates)
        System.out.println("sync   = " + syncCount);     // 400000
        System.out.println("atomic = " + atomicCount);   // 400000

        Thread worker = new Thread(() -> {
            while (running) { }                          // without volatile this may spin forever
            System.out.println("worker stopped");
        });
        worker.start();
        Thread.sleep(50);
        running = false;
        worker.join();

        try (var vt = Executors.newVirtualThreadPerTaskExecutor()) {          // Java 21
            Future<Boolean> f = vt.submit(() -> Thread.currentThread().isVirtual());
            System.out.println("virtual? " + f.get());                        // virtual? true
        }
    }
}

import java.util.*;
import java.util.concurrent.Executors;
import java.util.stream.*;

public class ModernJava {
    record Order(String customer, String city, double amount) {}       // Java 16: record

    sealed interface Payment permits Card, Bkash, Cash {}              // Java 17: sealed
    record Card(String last4) implements Payment {}
    record Bkash(String phone) implements Payment {}
    record Cash() implements Payment {}

    static String describe(Payment p) {                                // Java 21: switch patterns
        return switch (p) {                                            // exhaustive: no default
            case Card(String last4) -> "card ****" + last4;
            case Bkash(String phone) when phone.startsWith("017") -> "bKash (GP) " + phone;
            case Bkash(String phone) -> "bKash " + phone;
            case Cash c -> "cash";
        };
    }

    public static void main(String[] args) throws Exception {
        var orders = List.of(                                          // Java 10 var, Java 9 List.of
                new Order("Rina", "Dhaka", 1200), new Order("Arif", "Sylhet", 300),
                new Order("Mitu", "Dhaka", 800), new Order("Rina", "Dhaka", 450));

        Map<String, Double> bigByCity = orders.stream()                // Java 8 lambdas + streams
                .filter(o -> o.amount() >= 400)
                .collect(Collectors.groupingBy(Order::city, TreeMap::new,
                        Collectors.summingDouble(Order::amount)));
        System.out.println(bigByCity);                                 // {Dhaka=2450.0}

        Optional<Order> first = orders.stream().filter(o -> o.amount() > 5000).findFirst();
        System.out.println(first.map(Order::customer).orElse("none")); // none   (Java 8 Optional)

        Object obj = orders.get(1);
        if (obj instanceof Order(var who, var city, var amount) && amount < 500) {   // Java 21
            System.out.println(who + " from " + city + " placed a small order");     // Arif from Sylhet ...
        }
        System.out.println(describe(new Bkash("01711000000")));        // bKash (GP) 01711000000

        String json = """
                {"customer": "Rina", "total": 1200}
                """;                                                   // Java 15 text block
        System.out.print(json);

        try (var exec = Executors.newVirtualThreadPerTaskExecutor()) { // Java 21 virtual threads
            var futures = IntStream.range(0, 10_000)
                    .mapToObj(i -> exec.submit(() -> i * 2)).toList(); // Java 16 Stream.toList()
            System.out.println(futures.get(9_999).get());              // 19998
        }
    }
}

