public record CreateAccountRequest(
        @NotBlank @Size(max = 100) String ownerName,
        @NotBlank @Pattern(regexp = "01[3-9]\\d{8}") String phone,
        @NotNull @DecimalMin("0.00") BigDecimal openingBalance) {}

public record AccountResponse(Long id, String ownerName, BigDecimal balance) {
    public static AccountResponse from(Account a) {
        return new AccountResponse(a.getId(), a.getOwnerName(), a.getBalance());
    }
}

// ---------- repository: data access only (Account is a JPA @Entity, not shown)
public interface AccountRepository extends JpaRepository<Account, Long> {
    boolean existsByPhone(String phone);
}

// ---------- service: business rules and transactions
@Service
@Transactional(readOnly = true)
public class AccountService {
    private final AccountRepository accounts;

    public AccountService(AccountRepository accounts) { this.accounts = accounts; }

    public AccountResponse get(Long id) {
        return accounts.findById(id).map(AccountResponse::from)
                .orElseThrow(() -> new AccountNotFoundException(id));
    }

    @Transactional
    public AccountResponse open(CreateAccountRequest req) {
        if (accounts.existsByPhone(req.phone())) throw new DuplicateAccountException(req.phone());
        Account saved = accounts.save(new Account(req.ownerName(), req.phone(), req.openingBalance()));
        return AccountResponse.from(saved);
    }
}

// ---------- controller: HTTP in, HTTP out, no business logic
@RestController
@RequestMapping("/api/v1/accounts")
public class AccountController {
    private final AccountService service;

    public AccountController(AccountService service) { this.service = service; }

    @GetMapping("/{id}")
    public AccountResponse get(@PathVariable Long id) {            // 200 OK + JSON body
        return service.get(id);
    }

    @PostMapping
    public ResponseEntity<AccountResponse> open(@Valid @RequestBody CreateAccountRequest req) {
        AccountResponse created = service.open(req);
        URI location = URI.create("/api/v1/accounts/" + created.id());
        return ResponseEntity.created(location).body(created);     // 201 Created + Location header
    }
}

