@Service
public class TransferService {
    private final AccountRepository accounts;
    private final AuditService audit;            // a DIFFERENT bean, so calls go through its proxy

    public TransferService(AccountRepository accounts, AuditService audit) {
        this.accounts = accounts;
        this.audit = audit;
    }

    @Transactional                               // REQUIRED (default): join the caller's tx or start one
    public void transfer(long fromId, long toId, BigDecimal amount) {
        Account from = accounts.findById(fromId).orElseThrow();
        Account to = accounts.findById(toId).orElseThrow();
        audit.record("transfer " + fromId + " -> " + toId + ": " + amount);   // REQUIRES_NEW
        from.withdraw(amount);                   // may throw InsufficientFundsException (unchecked)
        to.deposit(amount);
    }                                            // no exception -> commit: dirty entities flushed as UPDATEs

    @Transactional(rollbackFor = StatementImportException.class)   // checked exceptions COMMIT by default
    public void importStatement(Path csv) throws StatementImportException {
        // ... parse and save rows ...
    }

    public void transferAll(List<TransferRequest> batch) {          // no @Transactional here
        for (TransferRequest r : batch) {
            transfer(r.fromId(), r.toId(), r.amount());   // SELF-INVOCATION: this.transfer(...) skips
        }                                                 // the proxy, so NO transaction is started
    }
}

@Service
public class AuditService {
    private final AuditRepository repo;

    public AuditService(AuditRepository repo) { this.repo = repo; }

    @Transactional(propagation = Propagation.REQUIRES_NEW)   // suspend the caller's tx, run in a new one
    public void record(String message) {
        repo.save(new AuditEntry(message));
    }                                                        // committed now, even if the caller rolls back
}

